				quads[6] = quads[2]; // x4
				quads[7] = quads[5]; // y5

				txtMark.setQuadPoints(quads);

		    }  

		    doc.save(&quot;tmpfile.pdf&quot;); //Output file name  
		}  
		finally  
		{  
