It could be a combination of things that caused the problem. Let me kind of show you how I handle the documents, from loading the template to saving the completed, merged document:
{code:java}
// File loaded into memory (essentially stored as a byte array, within a Document object)
byte[] data;

// Data is read from the byte array using ByteArrayInputStream
try(InputStream is = new ByteArrayInputStream (is))
{
    ...
}

// There are two processes involved. Filling and merging. It&apos;s not clear which one did the &quot; ) Tj 0 - 13 Td (&quot; thing, but merging is definitely where the IndexOutOfBoundsException exception was occurring

// The first process fills the PDF form fields, and saves it to a new byte array
final Document template;
final Map&lt;String, Object&gt; parameters;
try (InputStream is = template.openInputStream ()) // openInputStream returns ByteArrayInputStream for the typical Document implementation
{
	final PDDocument document = PDDocument.load (is);
	try
	{
		final PDDocumentCatalog catalog = document.getDocumentCatalog ();
		final PDAcroForm form = catalog.getAcroForm ();
		for (final Map.Entry&lt;String, Object&gt; e : parameters.entrySet ())
		{
			final PDField field = form.getField (e.getKey ());
			if (field != null)
			{
				if (field instanceof PDCheckbox)
				{
					final Object value = e.getValue ();
					final boolean boolValue = (value instanceof Boolean) ? (Boolean) value : Boolean.parseBoolean (e.getValue ().toString ());
					if (boolValue)
						((PDCheckbox) field).check ();
					else
						((PDCheckbox) field).unCheck ();
				}
				else
					field.setValue (e.getValue ().toString ());
			}
		}
		document.save (os);
	}
	finally
	{
		document.close ();
	}
}
catch (final IOException | COSVisitorException e)
{
	throw new RuntimeException (&quot;Exception thrown while populating PDF field data&quot;, e);
}

// The second process reads from multiple byte arrays, one for each document, merges them, and saves it to a new byte array
final List&lt;InputStream&gt; streamsToClose = new LinkedList&lt;&gt; ();
try
{
	final PDFMergerUtility mergePdf = new PDFMergerUtility ();
	for (final Document doc : this.parts)
	{
		Document pdf;
		if (MimeType.MIME_COMPARATOR.compare (doc.getMimeType (), &quot;pdf&quot;) == 0)
			pdf = doc;
		else if (doc.isConvertableTo (&quot;pdf&quot;))
			pdf = doc.convert (&quot;pdf&quot;);
		else
			throw new DocumentConversionException (&quot;Cannot merge document &apos;&quot; + doc + &quot;&apos; with id &apos;&quot; + doc.getId () + &quot;&apos; and MIME type &apos;&quot;
					+ doc.getMimeType () + &quot;&apos;: Only PDF documents allowed&quot;);
		final InputStream is = pdf.openInputStream ();
		streamsToClose.add (is);
		mergePdf.addSource (is);
	}
	try (ByteArrayOutputStream os = new ByteArrayOutputStream ())
	{
		mergePdf.setDestinationStream (os);

		///////////////////////////
		// This is where the IndexOutOfBoundsException would occur
		mergePdf.mergeDocuments ();
		///////////////////////////

		return new RawDocument (os.toByteArray (), &quot;application/pdf&quot;, null);
	}
	catch (final IOException | COSVisitorException e)
	{
		throw new DocumentConversionException (&quot;Exception occured during PDF document merge&quot;, e);
	}
}
finally
{
	final Iterator&lt;InputStream&gt; it = streamsToClose.iterator ();
	while (it.hasNext ())
		try (InputStream is = it.next ())
		{}
		catch (final IOException e)
		{
